CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_insert_own ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_private_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'display_name', '')); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.create_private_profile() FROM PUBLIC;
CREATE TRIGGER on_private_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_private_profile();
CREATE TABLE public.investigations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL DEFAULT 'Nova investigação', benefit text, facts jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.investigations TO authenticated;
GRANT ALL ON public.investigations TO service_role;
ALTER TABLE public.investigations ENABLE ROW LEVEL SECURITY;
CREATE POLICY investigations_owner ON public.investigations FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.investigation_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), investigation_id uuid NOT NULL REFERENCES public.investigations(id) ON DELETE CASCADE, client_id text NOT NULL, role text NOT NULL CHECK (role IN ('user','assistant')), parts jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(investigation_id,client_id));
GRANT SELECT, INSERT, DELETE ON public.investigation_messages TO authenticated;
GRANT ALL ON public.investigation_messages TO service_role;
ALTER TABLE public.investigation_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_owner_read ON public.investigation_messages FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.investigations i WHERE i.id = investigation_id AND i.user_id = auth.uid()));
CREATE POLICY messages_owner_insert ON public.investigation_messages FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.investigations i WHERE i.id = investigation_id AND i.user_id = auth.uid()));
CREATE POLICY messages_owner_delete ON public.investigation_messages FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.investigations i WHERE i.id = investigation_id AND i.user_id = auth.uid()));
CREATE INDEX investigation_messages_thread ON public.investigation_messages(investigation_id,created_at);
CREATE INDEX investigations_owner ON public.investigations(user_id,updated_at DESC);
CREATE POLICY private_documents_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'investigation-documents' AND (storage.foldername(name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.investigations i WHERE i.id::text = (storage.foldername(name))[2] AND i.user_id = auth.uid()));
CREATE POLICY private_documents_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'investigation-documents' AND (storage.foldername(name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.investigations i WHERE i.id::text = (storage.foldername(name))[2] AND i.user_id = auth.uid()));
CREATE POLICY private_documents_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'investigation-documents' AND (storage.foldername(name))[1] = auth.uid()::text AND EXISTS (SELECT 1 FROM public.investigations i WHERE i.id::text = (storage.foldername(name))[2] AND i.user_id = auth.uid()));